previewCss:
.darma-loader-darma-b15-stack-push-pop { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #ddd6fe); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .68); position: relative; overflow: hidden; }
.darma-loader-darma-b15-stack-push-pop .darma-loader-darma-b15-stack-push-pop__frame { position: absolute; left: 16%; right: 16%; bottom: 2%; height: 76%; border-radius: 0 0 8px 8px; border: 2px solid color-mix(in srgb, var(--accent) 30%, transparent); border-top: 0; }
.darma-loader-darma-b15-stack-push-pop span { position: absolute; left: 21%; width: 58%; height: 15%; border-radius: 4px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); }
.darma-loader-darma-b15-stack-push-pop span:nth-of-type(1) { bottom: 6%; animation: darma-loader-darma-b15-stack-push-pop-stk-first calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b15-stack-push-pop span:nth-of-type(2) { bottom: 24%; animation: darma-loader-darma-b15-stack-push-pop-stk-second calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b15-stack-push-pop span:nth-of-type(3) { bottom: 42%; animation: darma-loader-darma-b15-stack-push-pop-stk-third calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b15-stack-push-pop span:nth-of-type(4) { bottom: 60%; animation: darma-loader-darma-b15-stack-push-pop-stk-fourth calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b15-stack-push-pop-stk-first { 0%, 5% { transform: translateY(-360%); opacity: 0; } 13%, 85% { transform: translateY(0); opacity: 1; } 93%, 100% { transform: translateY(-360%); opacity: 0; } }
@keyframes darma-loader-darma-b15-stack-push-pop-stk-second { 0%, 15% { transform: translateY(-360%); opacity: 0; } 23%, 75% { transform: translateY(0); opacity: 1; } 83%, 100% { transform: translateY(-360%); opacity: 0; } }
@keyframes darma-loader-darma-b15-stack-push-pop-stk-third { 0%, 25% { transform: translateY(-360%); opacity: 0; } 33%, 65% { transform: translateY(0); opacity: 1; } 73%, 100% { transform: translateY(-360%); opacity: 0; } }
@keyframes darma-loader-darma-b15-stack-push-pop-stk-fourth { 0%, 35% { transform: translateY(-360%); opacity: 0; } 43%, 55% { transform: translateY(0); opacity: 1; } 63%, 100% { transform: translateY(-360%); opacity: 0; } }

